changeSet.sql:
UPDATE payouts
SET processing_at = created_at
WHERE status = 'PROCESSING' AND processing_at IS NULL;

ALTER TABLE payouts ADD CONSTRAINT chk_payouts_processing_requires_clock
    CHECK (status <> 'PROCESSING' OR processing_at IS NOT NULL);

DROP INDEX IF EXISTS idx_payouts_awaiting_settlement;

CREATE INDEX idx_payouts_awaiting_settlement
    ON payouts (processing_at)
    WHERE is_deleted = false AND settlement_reference IS NULL AND status IN ('PROCESSING');

rollback.sql:
DROP INDEX IF EXISTS idx_payouts_awaiting_settlement;

CREATE INDEX idx_payouts_awaiting_settlement
    ON payouts (created_at)
    WHERE is_deleted = false AND status IN ('PROCESSING');

ALTER TABLE payouts DROP CONSTRAINT IF EXISTS chk_payouts_processing_requires_clock;

changeSet.sql:
DROP INDEX IF EXISTS uk_payouts_settlement_reference;

CREATE UNIQUE INDEX uk_payouts_settlement_reference
    ON payouts (settlement_reference)
    WHERE settlement_reference IS NOT NULL;

rollback.sql:
DROP INDEX IF EXISTS uk_payouts_settlement_reference;

CREATE UNIQUE INDEX uk_payouts_settlement_reference
    ON payouts (settlement_reference)
    WHERE settlement_reference IS NOT NULL AND is_deleted = false;
